using System.Security.Cryptography;
using System.Text.Json;
using FinanceLogistics.Infrastructure.LogisticsTrade;
using FinanceLogistics.Application.Imports;
var parser=new TradeFileParser();var checks=0;
void Check(bool v,string name){if(!v)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);checks++;}
TradeParsePolicy Policy(TradeSourceProfile p)=>new(p.IsVerbatim?"AS_OF_SNAPSHOT":"EXPLICIT_RANGE",new(2026,1,1),new(2027,1,1));
ParsedTradeFile Parse(TradeSourceProfile p,Action<Dictionary<int,Dictionary<int,Cell>>>? change=null,TradeParsePolicy? policy=null,string filename="test.xlsx"){var rows=Fixture.Rows(p);change?.Invoke(rows);using var s=Fixture.Write(p,rows);return parser.Parse(s,filename,p.SourceCode,policy??Policy(p));}
bool Has(ParsedTradeFile f,string code)=>f.Issues.Any(i=>i.Code==code);
string Arg(string key){var i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:throw new ArgumentException("Missing "+key);}
if(args.Contains("--inspect")){
 try{var p=args.Contains("--profile")?TradeSourceProfiles.Get(Arg("--source"),Arg("--profile")):TradeSourceProfiles.Get(Arg("--source"));var path=Arg("--file");using var s=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);var hash=Convert.ToHexString(SHA256.HashData(s));s.Position=0;var policy=Policy(p);if(args.Contains("--start"))policy=policy with{Start=DateOnly.ParseExact(Arg("--start"),"yyyy-MM-dd"),EndExclusive=DateOnly.ParseExact(Arg("--end-exclusive"),"yyyy-MM-dd")};var f=parser.Parse(s,Path.GetFileName(path),p.SourceCode,policy,default,p.Code);Console.WriteLine(JsonSerializer.Serialize(new{source=p.SourceCode,sha256=hash,profile=p.Code,raw=f.Rows.Count,totalRows=f.DataRows,typed=f.Rows.Count(r=>r.Line!=null),errors=f.Errors,warnings=f.Warnings,groups=f.Issues.GroupBy(i=>new{i.Severity,i.Code}).Select(g=>new{g.Key.Severity,g.Key.Code,count=g.Count()}),errorCells=f.Issues.Where(i=>i.Severity=="ERROR")},new JsonSerializerOptions{WriteIndented=true}));return f.Errors==0?0:2;}catch(Exception e)when(e is IOException or ArgumentException or PoImportFault){Console.Error.WriteLine("Inspection could not start: "+e.Message);return 1;}
}
if(args.Contains("--samples")){var dir=Arg("--samples");Directory.CreateDirectory(dir);foreach(var p in TradeSourceProfiles.All){var rows=Fixture.Rows(p);using(var s=Fixture.Write(p,rows))using(var f=File.Create(Path.Combine(dir,p.SourceCode+"_01_valid.xlsx")))s.CopyTo(f);if(p.IsVerbatim)rows[1][1]=new Cell("UNKNOWN PACK HEADER");else rows[2][p.Fields.First(x=>x.Kind==TradeFieldKind.Date).Column]=new Cell("31/02/2026");using(var s=Fixture.Write(p,rows))using(var f=File.Create(Path.Combine(dir,p.SourceCode+"_02_invalid.xlsx")))s.CopyTo(f);}return 0;}
foreach(var p in TradeSourceProfiles.All){
 var label=p.SourceCode+": ";var f=Parse(p);Check(f.Errors==0&&f.Rows.Count==2&&f.Rows.All(x=>x.Line!=null),label+"two data rows");Check(Has(f,"DUPLICATE_ROW"),label+"duplicate retained");
 var reordered=Parse(p,rs=>{foreach(var row in rs.Values)(row[1],row[2])=(row[2],row[1]);});Check(reordered.Errors==0&&JsonSerializer.Serialize(f.Rows[0].Line)==JsonSerializer.Serialize(reordered.Rows[0].Line),label+"header reordered without changing values");Check(reordered.Rows[0].Cells.Single(x=>x.Ordinal==1).Header==p.Fields[1].Header,label+"raw header follows physical column");
 Check(Has(Parse(p,rs=>rs[1][1]=new Cell("UNKNOWN")),"UNKNOWN_HEADER"),label+"unknown header blocks");Check(Has(Parse(p,rs=>rs[1][2]=rs[1][1]),"DUPLICATE_HEADER"),label+"duplicate header blocks");Check(Has(Parse(p,rs=>rs[1].Remove(1)),"HEADER_MISMATCH"),label+"missing header blocks");Check(Has(Parse(p,rs=>rs[2][90]=new Cell("UNDECLARED")),"UNMAPPED_CELL"),label+"extra data retained and blocked");
 Check(Has(Parse(p,rs=>{rs.Remove(2);rs.Remove(3);}),"EMPTY_DATA_BATCH"),label+"empty cannot erase");Check(Has(Parse(p,policy:Policy(p) with{MaxRows=1}),"ROW_LIMIT"),label+"partial read cannot be ready");Check(Has(Parse(p,filename:"test.xls"),"FILE_LAYOUT_INVALID"),label+"renamed format rejected");Check(Has(Parse(p,policy:Policy(p) with{PeriodMode="UNKNOWN"}),"FILE_LAYOUT_INVALID"),label+"unknown policy rejected");
 var template=JsonSerializer.Serialize(new{profile=p.Code,schemaVersion=1,sheet=p.Sheet,headerPolicy="EXACT_NAMES",formulaPolicy=p.FormulaPolicy});Check(TradeSourcePolicy.Supports(p,template)&&!TradeSourcePolicy.Supports(p,template.Replace("EXACT_NAMES","GUESS")),label+"template exact");
 var mode=p.IsVerbatim?"AS_OF_SNAPSHOT":"EXPLICIT_RANGE";
 var policyJson=JsonSerializer.Serialize(new{ingestionMode="SNAPSHOT",maxBytes=10485760,maxRows=10000,coverageProperty=p.CoverageProperty,dateTextCentury=2000,logisticsPeriodMode=mode,coverageStart="2026-01-01",coverageEndExclusive="2027-01-01"});
 var resolved=TradeSourcePolicy.Resolve(policyJson,new(2026,10,1),new(2026,11,1),p);
 var frozen=JsonSerializer.Serialize(new{sourceCode=p.SourceCode,scopeCode=p.ScopeCode,profile=p.Code,coverageProperty=p.CoverageProperty,dateTextCentury=2000,periodMode=resolved.PeriodMode,startDate=resolved.Start.ToString("yyyy-MM-dd"),endDateExclusive=resolved.EndExclusive.ToString("yyyy-MM-dd"),maxRows=resolved.MaxRows,allowCachedAmountFormulas=true,formulaPolicy=p.FormulaPolicy,templateDefinition=JsonSerializer.Deserialize<JsonElement>(template)});
 Check(TradeSourcePolicy.Frozen(frozen,p)==resolved,label+"frozen worker policy roundtrip");
 try{TradeSourcePolicy.Frozen(frozen.Replace("\"maxRows\":10000","\"maxRows\":10001"),p);Check(false,label+"frozen row limit");}catch(FormatException){Check(true,label+"frozen row limit enforced");}
 if(p.IsVerbatim){var keep=Parse(p,rs=>{rs[2][2]=new Cell("  0000123  ");rs[2][5]=new Cell("NO YEAR");rs[2][6]=new Cell("#N/A","e");rs[3][1]=new Cell("45432","n");});Check(keep.Errors==0&&keep.Rows.Count==2&&(string?)keep.Rows[0].Line!["Cell"]=="  0000123  ",label+"whitespace and zeros unchanged");Check((string?)keep.Rows[0].Line!["AuthorizationDateRaw"]=="NO YEAR"&&(string?)keep.Rows[0].Line!["ExpiryDateRaw"]=="#N/A",label+"raw date/error preserved");Check((string?)keep.Rows[1].Line!["Pack"]=="45432",label+"numeric lexeme preserved");Check(Parse(p,rs=>{rs[2].Clear();rs[2][1]=new Cell("  ");}).Rows.Count==2,label+"whitespace-only row retained");var fm=Parse(p,rs=>rs[2][5]=new Cell("46029","n","1+1"));Check(fm.Errors==0&&fm.Rows[0].Cells.Single(c=>c.Ordinal==5).Formula=="=1+1"&&Has(fm,"SOURCE_FORMULA_PRESERVED"),label+"formula/cache preserved without execution");continue;}
 var id=p.Fields.First(x=>x.Kind==TradeFieldKind.Identifier);var num=p.Fields.First(x=>x.Kind==TradeFieldKind.Number);var date=p.Fields.First(x=>x.Kind==TradeFieldKind.Date);
 var placeholder=Parse(p,rs=>{rs[3].Clear();rs[3][num.Column]=new Cell(" - ");});Check(placeholder.Errors==0&&placeholder.Rows.Count==2&&placeholder.DataRows==1&&placeholder.Rows[1].Kind=="PLACEHOLDER",label+"dash template row kept as control");Check(Parse(p,rs=>rs[2][num.Column]=new Cell(" - ")).DataRows==2,label+"transaction with dash retained");
 Check((string?)f.Rows[0].Line![id.Property]=="000123",label+"text identifier zeros");Check(Has(Parse(p,rs=>rs[2][id.Column]=new Cell("1234567890123456","n")),"IDENTIFIER_PRECISION"),label+"numeric precision loss blocked");Check(Has(Parse(p,rs=>rs[2][num.Column]=new Cell("1.0000000000000000001","n")),"DECIMAL_PRECISION"),label+"no SQL rounding");var neg=Parse(p,rs=>rs[2][num.Column]=new Cell("-12.3401","n"));Check(neg.Errors==0&&Has(neg,"NEGATIVE_VALUE")&&(decimal?)neg.Rows[0].Line![num.Property]==-12.3401m,label+"negative exact");
 Check(Has(Parse(p,rs=>rs[2][date.Column]=new Cell("31/02/2026")),"INVALID_DATE"),label+"impossible date");Check(Has(Parse(p,rs=>rs[2][date.Column]=new Cell("12/02")),"INVALID_DATE"),label+"year not guessed");var outside=Parse(p,rs=>rs[2][p.Fields.Single(x=>x.Property==p.CoverageProperty).Column]=new Cell("12/02/2025"));Check(Has(outside,"WRONG_COVERAGE")&&outside.Rows.Count==2,label+"out of range retained");Check(Has(Parse(p,rs=>rs[2][date.Column]=new Cell("60","n")),"INVALID_DATE"),label+"Excel fictitious leap day blocked");Check(Has(Parse(p,rs=>rs[2][num.Column]=new Cell("#REF!","e")),"EXCEL_CELL_ERROR"),label+"Excel error blocked");
 var cached=Parse(p,rs=>rs[2][num.Column]=new Cell("3.25","n","SUM(A99:A101)"));Check(cached.Errors==0&&(decimal?)cached.Rows[0].Line![num.Property]==3.25m&&Has(cached,"FORMULA_CACHED_VALUE"),label+"formula never executed");Check(Has(Parse(p,rs=>rs[2][num.Column]=new Cell(null,"n","SUM(A99:A101)")),"FORMULA_CACHE_MISSING"),label+"missing cache blocked");Check(Has(Parse(p,rs=>rs[2][id.Column]=new Cell("000124","str","\"000123\"")),"FORMULA_CACHE_MISMATCH"),label+"literal cache mismatch");
 if(p.SourceCode.StartsWith("XK_")){Check(Has(Parse(p,rs=>{rs[1].Remove(35);rs[2].Remove(35);rs[3].Remove(35);}),"AWB_COLUMN_ABSENT"),label+"old AWB absence visible");var awb=Parse(p,rs=>{foreach(var row in rs.Values){row[40]=row[35];row.Remove(35);}rs[1][40]=new Cell("AWB/BL");rs[2][40]=new Cell("AWB00012");});Check(awb.Errors==0&&(string?)awb.Rows[0].Line!["AwbNumber"]=="AWB00012",label+"AWB anywhere by name");Check((bool?)f.Rows[0].Line!["NoCharge"]==false,label+"Excel boolean");}
}
foreach(var kind in new[]{"OTHER_IMPORT","OTHER_EXPORT"}){
 var a=TradeSourceProfiles.Get(kind+"_1000");var b=TradeSourceProfiles.Get(kind+"_6000");
 Check(a.Fields.SequenceEqual(b.Fields)&&a.Sheet==b.Sheet,kind+": shared layout");
 Check(a.ScopeCode=="SITE_1000"&&b.ScopeCode=="SITE_6000"&&a.Code!=b.Code,kind+": separate site/profile");
 try{TradeSourceProfiles.Get(a.SourceCode,b.Code);Check(false,"cross-site OTHER");}catch(PoImportFault){Check(true,kind+": cross-site profile rejected");}
}
try{TradeSourceProfiles.Get("PIN_TEST_6000");Check(false,"unsupported Pin");}catch(PoImportFault){Check(true,"Pin has no site6000");}
try{TradeSourceProfiles.Get("XK_1000","XK_6000_WORKBOOK_V1");Check(false,"cross source");}catch(PoImportFault){Check(true,"cross source profile rejected");}
Console.WriteLine($"Completed {checks} checks. Windows/SQL/API/SAML integration is separate.");return 0;
